// Automatically merge into window.translations for seamless integration with main.js data-i18n engine
(function () {
  function mergeBlogTranslations() {
    if (!window.translations) return;
    if (!window.translations.fr) window.translations.fr = {};
    if (!window.translations.darija) window.translations.darija = {};
    
    window.translations.fr.blogArticles = window.translation_blogs_javascript.fr.blogArticles;
    window.translations.darija.blogArticles = window.translation_blogs_javascript.darija.blogArticles;
  }

  mergeBlogTranslations();

  // Function to apply blog translations directly to article DOM elements
  window.applyBlogArticleTranslations = function(lang) {
    const currentLang = lang || (window.currentLang || localStorage.getItem('hicham_lang') || 'darija');
    const dict = window.translation_blogs_javascript[currentLang];
    if (!dict || !dict.blogArticles) return;

    // Translate article detail page if active
    const articlePage = document.querySelector('article[data-article-id]');
    if (articlePage) {
      const artId = articlePage.getAttribute('data-article-id');
      const data = dict.blogArticles[artId];
      if (data) {
        const titleEl = document.getElementById('article-title');
        const excerptEl = document.getElementById('article-excerpt');
        const catEl = document.getElementById('article-category');
        const dateEl = document.getElementById('article-date');
        const readEl = document.getElementById('article-readtime');
        const bodyEl = document.getElementById('article-body');

        if (titleEl && data.title) titleEl.innerHTML = data.title;
        if (excerptEl && data.excerpt) excerptEl.innerHTML = data.excerpt;
        if (catEl && data.category) catEl.innerHTML = data.category;
        if (dateEl && data.date) dateEl.innerHTML = data.date;
        if (readEl && data.readTime) readEl.innerHTML = data.readTime;
        if (bodyEl && data.content) bodyEl.innerHTML = data.content;
      }
    }

    // Translate blog list cards on blog.html if present
    document.querySelectorAll('[data-blog-card-id]').forEach(card => {
      const artId = card.getAttribute('data-blog-card-id');
      const data = dict.blogArticles[artId];
      if (data) {
        const cardTitle = card.querySelector('.blog-card-title');
        const cardExcerpt = card.querySelector('.blog-card-excerpt');
        const cardCat = card.querySelector('.blog-card-category');
        const cardRead = card.querySelector('.blog-card-read');

        if (cardTitle && data.title) cardTitle.innerHTML = data.title;
        if (cardExcerpt && data.excerpt) cardExcerpt.innerHTML = data.excerpt;
        if (cardCat && data.category) cardCat.innerHTML = data.category;
        if (cardRead && data.readTime) cardRead.innerHTML = data.readTime;
      }
    });
  };

  // Hook on DOMContentLoaded and on language change
  document.addEventListener('DOMContentLoaded', () => {
    mergeBlogTranslations();
    setTimeout(() => {
      const lang = window.currentLang || localStorage.getItem('hicham_lang') || 'darija';
      window.applyBlogArticleTranslations(lang);
    }, 50);
  });
})();
